'use strict';

var REPL = require( './../lib' );

function onCommand( cmd, success, res ) {
	console.log( cmd + ' = ' + res.toString() );
}

// Create a new REPL:
var repl = new REPL();
repl.on( 'command', onCommand );

// Execute a command:
repl.emit( 'input', '3 + 2' );

// Close the REPL:
repl.close();
console.log( 'REPL closed.' );
